import{_ as e,o,c as a,ae as r}from"./chunks/framework.EHGTsUvI.js";const u=JSON.parse('{"title":"Chocolate Milk Factory","description":"","frontmatter":{"title":"Chocolate Milk Factory"},"headers":[],"relativePath":"Main/Main/GeneralKnowledge/Factorys&Utilities/Factories/cm.md","filePath":"Main/Main/GeneralKnowledge/Factorys&Utilities/Factories/cm.md"}'),n={name:"Main/Main/GeneralKnowledge/Factorys&Utilities/Factories/cm.md"};function i(l,t,s,c,d,h){return o(),a("div",null,[...t[0]||(t[0]=[r(`<h1 id="chocolate-milk-factory" tabindex="-1">Chocolate Milk Factory <a class="header-anchor" href="#chocolate-milk-factory" aria-label="Permalink to &quot;Chocolate Milk Factory&quot;">​</a></h1><p>The Chocolate Milk Factory is a production building that combines <strong>Cocoa</strong> and <strong>Milk</strong> to produce Chocolate Milk.</p><p>Chocolate Milk is considered a high-value production chain, but requires several unlocks and pieces of equipment before it can be used efficiently.</p><h2 id="factory-information" tabindex="-1">Factory Information <a class="header-anchor" href="#factory-information" aria-label="Permalink to &quot;Factory Information&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Information</th><th>Details</th></tr></thead><tbody><tr><td>Purchase Price</td><td>50,000 Coins</td></tr><tr><td>Main Inputs</td><td>Cocoa &amp; Milk</td></tr><tr><td>Product</td><td>Chocolate Milk</td></tr><tr><td>Maximum Output</td><td>60 Jugs</td></tr><tr><td>Required License</td><td>Chocolate Milk License</td></tr><tr><td>Build Menu</td><td>Create &gt; Buildings</td></tr></tbody></table><p>The Chocolate Milk Factory costs <strong>50,000 Coins</strong> and can produce up to <strong>60 Chocolate Milk Jugs</strong> when fully supplied.</p><h2 id="required-materials" tabindex="-1">Required Materials <a class="header-anchor" href="#required-materials" aria-label="Permalink to &quot;Required Materials&quot;">​</a></h2><p>Each Chocolate Milk Jug requires:</p><table tabindex="0"><thead><tr><th>Material</th><th>Amount</th></tr></thead><tbody><tr><td>Cocoa</td><td>25</td></tr><tr><td>Regular Milk</td><td>10 Jugs</td></tr></tbody></table><p>Alternatively, Free-Range Milk can be used:</p><table tabindex="0"><thead><tr><th>Material</th><th>Amount</th></tr></thead><tbody><tr><td>Cocoa</td><td>25</td></tr><tr><td>Free-Range Milk</td><td>5 Jugs</td></tr></tbody></table><p>Free-Range Milk counts as <strong>2 Regular Milk</strong>, meaning only 5 Free-Range Milk is required for one Chocolate Milk Jug.</p><h3 id="full-production-batch" tabindex="-1">Full Production Batch <a class="header-anchor" href="#full-production-batch" aria-label="Permalink to &quot;Full Production Batch&quot;">​</a></h3><p>For the maximum <strong>60 Chocolate Milk Jugs</strong>, you will need:</p><table tabindex="0"><thead><tr><th>Material</th><th>Amount</th></tr></thead><tbody><tr><td>Cocoa</td><td>1,500</td></tr><tr><td>Regular Milk</td><td>600 Jugs</td></tr></tbody></table><p>Or:</p><table tabindex="0"><thead><tr><th>Material</th><th>Amount</th></tr></thead><tbody><tr><td>Cocoa</td><td>1,500</td></tr><tr><td>Free-Range Milk</td><td>300 Jugs</td></tr></tbody></table><h2 id="production-time" tabindex="-1">Production Time <a class="header-anchor" href="#production-time" aria-label="Permalink to &quot;Production Time&quot;">​</a></h2><p>A fixed production time for the Chocolate Milk Factory is not currently documented reliably.</p><p>Production requires the player to manually operate the factory&#39;s lever sequence after loading the required materials.</p><blockquote><p><strong>Note:</strong> The exact processing time should be confirmed in-game before being added as a fixed value.</p></blockquote><h2 id="products-produced" tabindex="-1">Products Produced <a class="header-anchor" href="#products-produced" aria-label="Permalink to &quot;Products Produced&quot;">​</a></h2><p>The Chocolate Milk Factory produces:</p><table tabindex="0"><thead><tr><th>Product</th><th>Maximum Amount</th></tr></thead><tbody><tr><td>Chocolate Milk Jug</td><td>60</td></tr></tbody></table><p>Each jug requires <strong>25 Cocoa and 10 Regular Milk</strong>, or <strong>25 Cocoa and 5 Free-Range Milk</strong>.</p><h2 id="selling-price" tabindex="-1">Selling Price <a class="header-anchor" href="#selling-price" aria-label="Permalink to &quot;Selling Price&quot;">​</a></h2><p>Chocolate Milk currently sells for approximately <strong>20,000 Coins per Jug</strong> according to the June 2026 community guide.</p><p>At approximately 20,000 Coins per jug:</p><p><strong>60 × 20,000 = 1,200,000 Coins</strong></p><p>A full production batch could therefore be worth approximately <strong>1.2 million Coins</strong> before considering costs and current market/selling values.</p><blockquote><p><strong>Note:</strong> Selling prices can change, so the in-game selling price should be treated as the final authority.</p></blockquote><h2 id="required-equipment" tabindex="-1">Required Equipment <a class="header-anchor" href="#required-equipment" aria-label="Permalink to &quot;Required Equipment&quot;">​</a></h2><p>To operate a Chocolate Milk Factory, you will need:</p><ul><li><strong>Chocolate Milk Factory</strong></li><li><strong>Chocolate Milk License</strong></li><li><strong>Cocoa Trees</strong></li><li><strong>Cocoa Harvester</strong></li><li><strong>Forest Soil</strong></li><li><strong>Cows</strong></li><li><strong>Milk production setup</strong></li><li><strong>Milk storage/transport</strong></li><li><strong>Suitable trailer or transport vehicle</strong></li></ul><p>The <strong>Oxbo 3220</strong> is listed at approximately <strong>140,000 Coins</strong> and can be used to harvest Cocoa. The Oxbo 4220 is another compatible option.</p><p>Cocoa itself requires the <strong>Chocolate Milk License</strong>, with the Forestry License required first.</p><h2 id="how-to-use-the-factory" tabindex="-1">How to Use the Factory <a class="header-anchor" href="#how-to-use-the-factory" aria-label="Permalink to &quot;How to Use the Factory&quot;">​</a></h2><h3 id="_1-unlock-the-chocolate-milk-license" tabindex="-1">1. Unlock the Chocolate Milk License <a class="header-anchor" href="#_1-unlock-the-chocolate-milk-license" aria-label="Permalink to &quot;1. Unlock the Chocolate Milk License&quot;">​</a></h3><p>Before producing Chocolate Milk, you need to unlock the required <strong>Chocolate Milk License</strong> through the game&#39;s Goals progression.</p><p>The Forestry License is required before the Chocolate Milk License.</p><h3 id="_2-set-up-cocoa" tabindex="-1">2. Set Up Cocoa <a class="header-anchor" href="#_2-set-up-cocoa" aria-label="Permalink to &quot;2. Set Up Cocoa&quot;">​</a></h3><p>Cocoa Trees are grown on <strong>Forest Soil</strong>.</p><p>Cocoa requires a compatible harvester such as the <strong>Oxbo 3220</strong> or <strong>Oxbo 4220</strong> to collect the Cocoa.</p><h3 id="_3-produce-milk" tabindex="-1">3. Produce Milk <a class="header-anchor" href="#_3-produce-milk" aria-label="Permalink to &quot;3. Produce Milk&quot;">​</a></h3><p>You will also need a supply of milk from cows.</p><p>Regular Milk can be used directly, while Free-Range Milk provides a 2:1 conversion and can reduce the amount of milk required per jug.</p><h3 id="_4-load-the-factory" tabindex="-1">4. Load the Factory <a class="header-anchor" href="#_4-load-the-factory" aria-label="Permalink to &quot;4. Load the Factory&quot;">​</a></h3><p>Place the required Cocoa and Milk onto the elevated loading platform on the factory.</p><p>The minimum recipe is:</p><p><strong>25 Cocoa + 10 Regular Milk → 1 Chocolate Milk Jug</strong></p><p>or:</p><p><strong>25 Cocoa + 5 Free-Range Milk → 1 Chocolate Milk Jug</strong></p><p>The factory must have enough ingredients for at least one complete recipe before production can begin.</p><h3 id="_5-start-production" tabindex="-1">5. Start Production <a class="header-anchor" href="#_5-start-production" aria-label="Permalink to &quot;5. Start Production&quot;">​</a></h3><p>Enter the factory and activate the first lever.</p><p>Continue following the prompts and pull the remaining levers in the required sequence.</p><blockquote><p><strong>Important:</strong> Skipping a lever or pulling them out of order can interrupt the production process.</p></blockquote><h3 id="_6-collect-the-chocolate-milk" tabindex="-1">6. Collect the Chocolate Milk <a class="header-anchor" href="#_6-collect-the-chocolate-milk" aria-label="Permalink to &quot;6. Collect the Chocolate Milk&quot;">​</a></h3><p>Once production has finished, collect the Chocolate Milk Jugs from the output area.</p><p>A fully supplied factory can produce up to <strong>60 Jugs</strong> in one batch.</p><h3 id="_7-transport-and-sell" tabindex="-1">7. Transport and Sell <a class="header-anchor" href="#_7-transport-and-sell" aria-label="Permalink to &quot;7. Transport and Sell&quot;">​</a></h3><p>Load the Chocolate Milk onto a suitable trailer or transport vehicle and take it to a selling location.</p><p>At approximately <strong>20,000 Coins per Jug</strong>, Chocolate Milk can provide a significant return when produced at scale.</p><h2 id="chocolate-milk-production-chain" tabindex="-1">Chocolate Milk Production Chain <a class="header-anchor" href="#chocolate-milk-production-chain" aria-label="Permalink to &quot;Chocolate Milk Production Chain&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Forest Soil</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Cocoa Trees</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Cocoa</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>             ┌──────────────┐</span></span>
<span class="line"><span>    Milk ───────→│              │</span></span>
<span class="line"><span>    Cocoa ──────→│ Chocolate    │</span></span>
<span class="line"><span>             │ Milk Factory │</span></span>
<span class="line"><span>             │              │</span></span>
<span class="line"><span>             └──────┬───────┘</span></span>
<span class="line"><span>                    ↓</span></span>
<span class="line"><span>             Chocolate Milk</span></span>
<span class="line"><span>                    ↓</span></span>
<span class="line"><span>                  Sell</span></span></code></pre></div><h2 id="costs-to-consider" tabindex="-1">Costs to Consider <a class="header-anchor" href="#costs-to-consider" aria-label="Permalink to &quot;Costs to Consider&quot;">​</a></h2><p>The Chocolate Milk Factory itself costs <strong>50,000 Coins</strong>, but the complete production setup is considerably more expensive.</p><p>A basic setup may also require:</p><table tabindex="0"><thead><tr><th>Item</th><th>Approximate Cost</th></tr></thead><tbody><tr><td>Chocolate Milk Factory</td><td>50,000 Coins</td></tr><tr><td>Oxbo 3220</td><td>140,000 Coins</td></tr><tr><td>Cocoa Seeds</td><td>70,000 Coins per 50-tree batch</td></tr><tr><td>Cows &amp; Barns</td><td>Varies</td></tr><tr><td>Trailer</td><td>Varies</td></tr><tr><td>Forest Soil</td><td>Varies</td></tr></tbody></table><p>The community guide estimates a minimum setup of around <strong>260,000 Coins</strong> before additional barns, cows, fencing and trailers are included.</p><blockquote><p><strong>Tip:</strong> Chocolate Milk is generally more suited to mid-to-late game players because of the high initial investment and the number of licenses, animals, crops and vehicles required.</p></blockquote>`,71)])])}const g=e(n,[["render",i]]);export{u as __pageData,g as default};
